// TH14 v1.00b st07bs.ecl::Boss6 (extra stage 6th nonspell), source lines 588-640.
// source_start is card frame 120 (standard opening buffer); see report.md.

const TIME_LIMIT: int = 3424;
const OPENING_BUFFER: int = 120;
const BOSS_HP: int = 14000;
const BOSS_HP_THRESHOLD: int = 3000;

// Boss6_at: mode10 alternating-layer ring, 40 ways x 3 layers, 1 degree layer offset.
const SHOT_COLOR: int = 8;
const WAYS: int = 40;
const RING_STEP: int = 1638;    // 9deg, source R(i)=2*pi*i/40
const HALF_SPAN: int = 31941;   // 19.5 * RING_STEP, fan centre -> first bullet
const LAYER_OFFSET: int = 182;  // 1deg, etAngle delta in the firing loop
const VOLLEYS: int = 41;        // source fires at ~141+70k; last one at ~2941 < 3000
const VOLLEY_WAIT: int = 70;
const TURN_STEP: int = 40503;   // source 3.883222 rad, sign flips every 8 volleys

// ET_DIST 16 minus the ANIM a=1 entry back-offset 4*speed (spawn animation omitted,
// its physical displacement kept): 16-4*1.6 and 16-4*1.58.
// Bullets are TH14 sprites; only the motion/EX semantics are synthetic.

xformdef RICE_BOUNCE {
    bounce_arm(7, 1); // source bounce mask U/L/R (1+4+8) -> target L/R/U bits (1+2+4)
}

// Source Boss6_at lines 664-666: etAngle(alpha, 1deg); etOn. Per-mode geometry:
// q0 angle=alpha+i*9deg; q1 angle=alpha-1deg-i*9deg; q2 angle=alpha+1deg+i*9deg.
sub fire_volley(base: int) {
    sh_reset(0);
    sh_sprite(0, TH14_RICE, SHOT_COLOR);
    sh_offset(0, 0fx, 24fx);   // source etOffset(0, 0, 24)
    sh_ring(0, 0);             // fan; creation order has no consumer here
    sh_aim(0, 0);              // source etAim mode 10 is fixed-direction
    sh_count(0, WAYS, 1);
    sh_xform(0, RICE_BOUNCE);

    sh_speed(0, 1.6fx, 0fx);
    sh_dist(0, 9.6fx);
    sh_angle(0, (base + HALF_SPAN) as angle, RING_STEP as angle);
    sh_fire(0);

    sh_speed(0, 1.58fx, 0fx);
    sh_dist(0, 9.68fx);
    sh_angle(0, (base - LAYER_OFFSET - HALF_SPAN) as angle, (0 - RING_STEP) as angle);
    sh_fire(0);

    sh_speed(0, 1.58fx, 0fx);
    sh_dist(0, 9.68fx);
    sh_angle(0, (base + LAYER_OFFSET + HALF_SPAN) as angle, RING_STEP as angle);
    sh_fire(0);
}

async sub boss_attack() {
    // Source 656: %A = %RANDRAD (-pi..pi), %B = 3.883222 rad, D=8 per direction cycle.
    var alpha: int = rand(65536) - 32768;
    var step: int = TURN_STEP;
    var inner: int = 0;
    var volley: int = 0;
    while volley < VOLLEYS {
        fire_volley(alpha);
        alpha = alpha + step;
        inner = inner + 1;
        if inner == 8 {
            inner = 0;
            step = 0 - step;
        }
        volley = volley + 1;
        wait(VOLLEY_WAIT);
    }
}

// moveRand(60, 4, 1.0): fixed random direction, speed 1-k/60, no limit in this card.
sub move_rand_once() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -25fx {
        a = r / 3;
    } else if $self_x > 25fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    var cx: fx = cos(a as angle);
    var cy: fx = sin(a as angle);
    var k: int = 1;
    while k <= 60 {
        var speed: fx = ((60 - k) as fx) / 60fx;
        move_vel_xy(0, cx * speed, cy * speed, EASE_LINEAR);
        wait(1);
        k = k + 1;
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
}

async sub boss_main() {
    // Boss() context: setHurtbox/setHitbox(48,48) -> circular radius 24.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // 591-601: A/B/C, lifeSet(14000) via spawn hp, timerReset is the card reference.
    wait(60);           // 625
    // 626 moveLimitReset: independent card inherits no previous limit.
    // 627-631 EffChargePoint2 / ANM / sounds are presentation and omitted.
    wait(80);           // 631
    spawn boss_attack(); // 632 callAsync Boss6_at
    loop {              // 633 -> 1348
        wait(120);
        move_rand_once();
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, BOSS_HP_THRESHOLD);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, BOSS_HP, 0, 0, 0, control);
    loop { wait(600); }
}

